export type AgentCommandRequest = {
	command: string;
	stdin?: string;
};

export type AgentTerminalResult = {
	aborted?: boolean;
	durationMs: number;
	exitCode: number;
	mutationMayContinue?: boolean;
	poisoned?: boolean;
	settled: boolean;
	stderr: string;
	stdout: string;
	timedOut?: boolean;
	truncated: boolean;
	workspaceChanged?: boolean;
};

export type AgentCommandExecutor = {
	execute(request: AgentCommandRequest, options?: { signal?: AbortSignal }): Promise<AgentTerminalResult>;
};

export type AgentTerminalEntry = {
	command: string;
	finishedAt?: number;
	id: string;
	result?: AgentTerminalResult;
	startedAt: number;
	status: 'cancelled' | 'failed' | 'running' | 'succeeded';
};

export type AgentActiveCommand = Pick<AgentTerminalEntry, 'command' | 'id' | 'startedAt'>;

export type AgentCommandRuntimeState = {
	mutationMayContinue: boolean;
	poisoned: boolean;
	running: boolean;
};

import type {
	AgentCommandExecutor,
	AgentCommandRequest,
	AgentCommandRuntimeState,
	AgentTerminalResult,
} from './command-types';

export const MaxAgentCommandBytes = 16 * 1024;
export const MaxAgentCommandStdinBytes = 256 * 1024;
export const MaxAgentCommandOutputBytes = 256 * 1024;
export const DefaultAgentCommandCancelSettleGraceMs = 1_000;

export type AgentCommandRuntime = {
	cancelCurrent(reason?: unknown): void;
	cancelCurrentAndWait(reason?: unknown): Promise<AgentCommandRuntimeState>;
	execute(
		request: AgentCommandRequest,
		options?: { onAcquired?: () => void; signal?: AbortSignal },
	): Promise<AgentTerminalResult>;
	getState(): AgentCommandRuntimeState;
};

export type AgentCommandRuntimeOptions = {
	cancelSettleGraceMs?: number;
};

type ExecutorOutcome = { error: unknown; kind: 'error' } | { kind: 'result'; result: AgentTerminalResult };
type CancellationOutcome = { kind: 'cancelled' };
type GraceExpiredOutcome = { kind: 'grace-expired' };

export function createAgentCommandRuntime(
	executor: AgentCommandExecutor,
	options: AgentCommandRuntimeOptions = {},
): AgentCommandRuntime {
	const cancelSettleGraceMs = resolveCancelSettleGrace(options.cancelSettleGraceMs);
	let running = false;
	let poisoned = false;
	let mutationMayContinue = false;
	let activeController: AbortController | undefined;
	let activeCompletion: Promise<void> | undefined;
	return {
		cancelCurrent(reason = 'cancelled') {
			activeController?.abort(reason);
		},
		async cancelCurrentAndWait(reason = 'cancelled') {
			activeController?.abort(reason);
			await activeCompletion;
			return { mutationMayContinue, poisoned, running };
		},
		async execute(request, executeOptions) {
			if (poisoned) return limitedResult('执行器已被未完成的命令污染，请替换执行器后重试。', 125, true);
			if (running) return limitedResult('已有命令正在执行。', 125, false);
			if (utf8Bytes(request.command) > MaxAgentCommandBytes) {
				return limitedResult(`命令超过 ${MaxAgentCommandBytes} 字节限制。`, 126, false);
			}
			if (utf8Bytes(request.stdin ?? '') > MaxAgentCommandStdinBytes) {
				return limitedResult(`标准输入超过 ${MaxAgentCommandStdinBytes} 字节限制。`, 126, false);
			}
			running = true;
			let finishCompletion!: () => void;
			const completion = new Promise<void>((resolve) => {
				finishCompletion = resolve;
			});
			activeCompletion = completion;
			const startedAt = now();
			const controller = new AbortController();
			activeController = controller;
			const onExternalAbort = () => controller.abort(executeOptions?.signal?.reason);
			executeOptions?.signal?.addEventListener('abort', onExternalAbort, { once: true });
			if (executeOptions?.signal?.aborted) onExternalAbort();
			let notifyCancelled: (() => void) | undefined;
			const cancellation = new Promise<CancellationOutcome>((resolve) => {
				notifyCancelled = () => resolve({ kind: 'cancelled' });
			});
			const onRuntimeAbort = () => notifyCancelled?.();
			controller.signal.addEventListener('abort', onRuntimeAbort, { once: true });
			if (controller.signal.aborted) onRuntimeAbort();
			try {
				executeOptions?.onAcquired?.();
				let delegated: Promise<AgentTerminalResult>;
				try {
					delegated = executor.execute(
						{ command: request.command, stdin: request.stdin },
						{ signal: controller.signal },
					);
				} catch (error) {
					delegated = Promise.reject(error);
				}
				const executorOutcome: Promise<ExecutorOutcome> = delegated.then(
					(result) => ({ kind: 'result', result }),
					(error: unknown) => ({ error, kind: 'error' }),
				);
				const first = await Promise.race([executorOutcome, cancellation]);
				const outcome =
					first.kind === 'cancelled'
						? await settleWithinCancellationGrace(executorOutcome, cancelSettleGraceMs)
						: first;
				if (outcome.kind === 'grace-expired') {
					poisoned = true;
					mutationMayContinue = true;
					return cancellationDidNotSettleResult(startedAt, cancelSettleGraceMs);
				}
				if (outcome.kind === 'error') {
					return {
						durationMs: Math.max(0, now() - startedAt),
						exitCode: 1,
						settled: true,
						stderr: toErrorMessage(outcome.error).slice(0, 1024),
						stdout: '',
						truncated: false,
					};
				}
				const output = boundOutput(outcome.result.stdout, outcome.result.stderr, MaxAgentCommandOutputBytes);
				const result: AgentTerminalResult = {
					...outcome.result,
					durationMs: safeDuration(outcome.result.durationMs, startedAt),
					settled: outcome.result.settled === true,
					stderr: output.stderr,
					stdout: output.stdout,
					truncated: outcome.result.truncated || output.truncated,
				};
				if (!result.settled || result.mutationMayContinue) mutationMayContinue = true;
				if (!result.settled || result.mutationMayContinue || result.poisoned) poisoned = true;
				return { ...result, poisoned: poisoned || result.poisoned };
			} finally {
				executeOptions?.signal?.removeEventListener('abort', onExternalAbort);
				controller.signal.removeEventListener('abort', onRuntimeAbort);
				if (activeController === controller) activeController = undefined;
				running = false;
				finishCompletion();
				if (activeCompletion === completion) activeCompletion = undefined;
			}
		},
		getState: () => ({ mutationMayContinue, poisoned, running }),
	};
}

function cancellationDidNotSettleResult(startedAt: number, graceMs: number): AgentTerminalResult {
	return {
		aborted: true,
		durationMs: Math.max(0, now() - startedAt),
		exitCode: 130,
		mutationMayContinue: true,
		poisoned: true,
		settled: false,
		stderr: `命令取消后未在 ${graceMs} 毫秒内结束；底层执行仍可能继续，运行时已污染。\n`,
		stdout: '',
		truncated: false,
	};
}

async function settleWithinCancellationGrace(
	outcome: Promise<ExecutorOutcome>,
	graceMs: number,
): Promise<ExecutorOutcome | GraceExpiredOutcome> {
	let timer: ReturnType<typeof setTimeout> | undefined;
	try {
		return await Promise.race([
			outcome,
			new Promise<GraceExpiredOutcome>((resolve) => {
				timer = setTimeout(() => resolve({ kind: 'grace-expired' }), graceMs);
			}),
		]);
	} finally {
		if (timer !== undefined) clearTimeout(timer);
	}
}

function resolveCancelSettleGrace(value: number | undefined): number {
	if (value === undefined) return DefaultAgentCommandCancelSettleGraceMs;
	if (!Number.isFinite(value) || value < 0) throw new RangeError('cancelSettleGraceMs 必须是有限的非负数。');
	return value;
}

function limitedResult(message: string, exitCode: number, isPoisoned: boolean): AgentTerminalResult {
	return {
		durationMs: 0,
		exitCode,
		poisoned: isPoisoned,
		settled: true,
		stderr: `${message}\n`,
		stdout: '',
		truncated: false,
	};
}

function boundOutput(stdout: string, stderr: string, limit: number) {
	const first = truncateUtf8(stdout, limit);
	const second = truncateUtf8(stderr, Math.max(0, limit - first.bytes));
	return { stdout: first.value, stderr: second.value, truncated: first.truncated || second.truncated };
}

function truncateUtf8(value: string, limit: number): { bytes: number; truncated: boolean; value: string } {
	const bytes = new TextEncoder().encode(value);
	if (bytes.byteLength <= limit) return { bytes: bytes.byteLength, truncated: false, value };
	let end = limit;
	while (end > 0 && (bytes[end] & 0xc0) === 0x80) end -= 1;
	return { bytes: end, truncated: true, value: new TextDecoder().decode(bytes.slice(0, end)) };
}

function safeDuration(value: number, startedAt: number): number {
	return Number.isFinite(value) && value >= 0 ? value : Math.max(0, now() - startedAt);
}

function toErrorMessage(error: unknown): string {
	return error instanceof Error ? error.message : String(error);
}

function utf8Bytes(value: string): number {
	return new TextEncoder().encode(value).byteLength;
}

function now(): number {
	return typeof performance === 'undefined' ? Date.now() : performance.now();
}

import type { AgentTerminalEntry, AgentTerminalResult } from './command-types';

export const MaxAgentTerminalEntries = 64;

export function appendAgentTerminalEntry(
	entries: readonly AgentTerminalEntry[],
	entry: AgentTerminalEntry,
): AgentTerminalEntry[] {
	return [...entries, entry].slice(-MaxAgentTerminalEntries);
}

export function appendCompletedAgentTerminalEntry(
	entries: readonly AgentTerminalEntry[],
	entry: Pick<AgentTerminalEntry, 'command' | 'id' | 'startedAt'>,
	result: AgentTerminalResult,
	finishedAt = Date.now(),
): AgentTerminalEntry[] {
	return completeAgentTerminalEntry(
		appendAgentTerminalEntry(entries, { ...entry, status: 'running' }),
		entry.id,
		result,
		finishedAt,
	);
}

export function completeAgentTerminalEntry(
	entries: readonly AgentTerminalEntry[],
	id: string,
	result: AgentTerminalResult,
	finishedAt = Date.now(),
): AgentTerminalEntry[] {
	return entries.map((entry) =>
		entry.id === id
			? {
					...entry,
					finishedAt,
					result,
					status: result.aborted ? 'cancelled' : result.exitCode === 0 ? 'succeeded' : 'failed',
				}
			: entry,
	);
}

import { type ToolSet, tool } from 'ai';
import { z } from 'zod';
import { type AgentWorkspace, resolveAgentWorkspacePath } from '../agent-work';
import { type AgentCommandRuntime, MaxAgentCommandStdinBytes } from './command-runtime';
import type { AgentTerminalResult } from './command-types';

export const MaxAgentWorkspaceWriteBytes = 64 * 1024;

export type CreateAgentCodingToolsOptions = {
	onCommandFinish?: (input: {
		acquired: boolean;
		command: string;
		result: AgentTerminalResult;
		toolCallId: string;
	}) => void;
	onCommandStart?: (input: { command: string; toolCallId: string }) => void;
	onWorkspaceChanged?: () => void;
	runtime: AgentCommandRuntime;
	workspace: AgentWorkspace;
};

export function createAgentCodingTools({
	onCommandFinish,
	onCommandStart,
	onWorkspaceChanged,
	runtime,
	workspace,
}: CreateAgentCodingToolsOptions): ToolSet {
	return {
		workspace_write: tool({
			description: '在工作区根目录内写入不超过 64 KiB 的 UTF-8 文件。',
			inputSchema: z.object({
				content: z.string().max(MaxAgentWorkspaceWriteBytes),
				path: z.string().min(1).max(4096),
			}),
			needsApproval: true,
			execute: async ({ content, path }, { abortSignal }) => {
				const bytes = utf8Bytes(content);
				if (bytes > MaxAgentWorkspaceWriteBytes) {
					return { code: 'too-large', limitBytes: MaxAgentWorkspaceWriteBytes, ok: false };
				}
				try {
					const resolved = resolveAgentWorkspacePath(workspace.rootPath, path);
					await workspace.fileSystem.writeFile(resolved, content, { overwrite: true, signal: abortSignal });
					onWorkspaceChanged?.();
					return { bytes, ok: true, path: resolved };
				} catch (error) {
					return toolError(error);
				}
			},
		}),
		bash: tool({
			description: '通过宿主注入的有界执行器运行非交互命令。',
			inputSchema: z.object({
				command: z
					.string()
					.min(1)
					.max(16 * 1024),
				stdin: z.string().max(MaxAgentCommandStdinBytes).optional(),
			}),
			needsApproval: true,
			execute: async ({ command, stdin }, { abortSignal, toolCallId }) => {
				let acquired = false;
				const result = await runtime.execute(
					{ command, stdin },
					{
						onAcquired: () => {
							acquired = true;
							onCommandStart?.({ command, toolCallId });
						},
						signal: abortSignal,
					},
				);
				onCommandFinish?.({ acquired, command, result, toolCallId });
				if (result.workspaceChanged) onWorkspaceChanged?.();
				return {
					aborted: result.aborted ?? false,
					durationMs: Math.round(result.durationMs),
					exitCode: result.exitCode,
					poisoned: result.poisoned ?? false,
					settled: result.settled,
					stderr: result.stderr,
					stdout: result.stdout,
					timedOut: result.timedOut ?? false,
					truncated: result.truncated,
					workspaceChanged: result.workspaceChanged ?? false,
				};
			},
		}),
	};
}

function toolError(error: unknown) {
	if (error instanceof Error && error.name === 'AbortError') return { code: 'aborted', ok: false };
	const code =
		typeof error === 'object' && error !== null && 'code' in error ? String(error.code).slice(0, 64) : 'failed';
	return { code, message: (error instanceof Error ? error.message : '写入失败。').slice(0, 256), ok: false };
}

function utf8Bytes(value: string): number {
	return new TextEncoder().encode(value).byteLength;
}

import type { JustBashAgentSession } from '@wener/common/fs/just-bash';
import type { AgentCommandExecutor } from './command-types';

export function createJustBashCommandExecutor(session: JustBashAgentSession): AgentCommandExecutor {
	return {
		async execute({ command, stdin }, { signal } = {}) {
			const result = await session.exec(command, { signal, stdin });
			return {
				aborted: result.aborted,
				durationMs: result.durationMs,
				exitCode: result.exitCode,
				mutationMayContinue: result.mutationMayContinue,
				poisoned: result.poisoned,
				settled: result.settled,
				stderr: result.stderr,
				stdout: result.stdout,
				timedOut: result.timedOut,
				truncated: result.truncated,
				workspaceChanged: result.workspaceChanged,
			};
		},
	};
}

'use client';

import { Play, Square } from 'lucide-react';
import type { ComponentPropsWithRef, FormEvent } from 'react';
import { cn } from '@/lib/utils';
import type { AgentActiveCommand, AgentTerminalEntry } from './command-types';

export type AgentTerminalMessages = {
	cancel: string;
	command: string;
	empty: string;
	exitCode: (code: number) => string;
	poisoned: string;
	run: string;
	truncated: string;
};

export const defaultAgentTerminalMessages: AgentTerminalMessages = {
	cancel: '取消命令',
	command: '命令',
	empty: '尚未运行命令。',
	exitCode: (code) => `退出码 ${code}`,
	poisoned: '执行器已污染，需替换运行时。',
	run: '运行命令',
	truncated: '输出已截断',
};

export type AgentTerminalProps = ComponentPropsWithRef<'section'> & {
	activeCommand?: AgentActiveCommand;
	command: string;
	entries: readonly AgentTerminalEntry[];
	messages?: Partial<AgentTerminalMessages>;
	onCancel?: (id: string) => void;
	onCommandChange: (command: string) => void;
	onRun?: (command: string) => void;
	poisoned?: boolean;
};

export function AgentTerminal({
	activeCommand,
	className,
	command,
	entries,
	messages,
	onCancel,
	onCommandChange,
	onRun,
	poisoned = false,
	...props
}: AgentTerminalProps) {
	const copy = { ...defaultAgentTerminalMessages, ...messages };
	const submit = (event: FormEvent<HTMLFormElement>) => {
		event.preventDefault();
		const value = command.trim();
		if (value && !activeCommand && !poisoned) onRun?.(value);
	};
	return (
		<section
			data-slot='agent-terminal'
			aria-label='终端'
			className={cn('bg-neutral text-neutral-content flex size-full min-h-0 flex-col', className)}
			{...props}
		>
			<form className='border-neutral-content/20 flex shrink-0 gap-2 border-b p-2' onSubmit={submit}>
				<label className='min-w-0 flex-1'>
					<span className='sr-only'>{copy.command}</span>
					<input
						aria-label={copy.command}
						className='input input-sm bg-neutral text-neutral-content border-neutral-content/25 w-full font-mono'
						disabled={Boolean(activeCommand) || poisoned}
						spellCheck={false}
						value={command}
						onChange={(event) => onCommandChange(event.currentTarget.value)}
					/>
				</label>
				{activeCommand ? (
					<button type='button' className='btn btn-error btn-sm' onClick={() => onCancel?.(activeCommand.id)}>
						<Square aria-hidden='true' className='size-3.5 fill-current' />
						{copy.cancel}
					</button>
				) : (
					<button type='submit' className='btn btn-primary btn-sm' disabled={!command.trim() || poisoned || !onRun}>
						<Play aria-hidden='true' className='size-4' />
						{copy.run}
					</button>
				)}
			</form>
			{poisoned ? (
				<div role='alert' className='bg-error/20 text-error-content px-3 py-2 text-xs'>
					{copy.poisoned}
				</div>
			) : null}
			<div className='min-h-0 flex-1 overflow-auto p-3 font-mono text-xs'>
				{entries.length === 0 ? <p className='text-neutral-content/55'>{copy.empty}</p> : null}
				{entries.map((entry) => (
					<TerminalEntryView key={entry.id} entry={entry} copy={copy} />
				))}
				{activeCommand && !entries.some((entry) => entry.id === activeCommand.id) ? (
					<pre className='mb-4 whitespace-pre-wrap'>
						<span className='text-success'>$</span> {activeCommand.command}
						{'\n'}运行中…
					</pre>
				) : null}
			</div>
		</section>
	);
}

function TerminalEntryView({ entry, copy }: { entry: AgentTerminalEntry; copy: AgentTerminalMessages }) {
	const result = entry.result;
	return (
		<pre
			data-terminal-entry={entry.id}
			className='border-neutral-content/15 mb-4 border-b pb-4 break-words whitespace-pre-wrap last:border-0'
		>
			<span className='text-success'>$</span> {entry.command}
			{'\n'}
			{result?.stdout ?? ''}
			{result?.stderr ? <span className='text-error'>{result.stderr}</span> : null}
			{result ? (
				<span className='text-neutral-content/55'>
					{'\n'}[{copy.exitCode(result.exitCode)} · {Math.round(result.durationMs)} ms
					{result.truncated ? ` · ${copy.truncated}` : ''}]
				</span>
			) : (
				<span className='text-neutral-content/55'>运行中…</span>
			)}
		</pre>
	);
}

'use client';

import { TerminalSquare } from 'lucide-react';
import type { ComponentPropsWithRef } from 'react';
import { AgentWork, type AgentWorkProps, type AgentWorkTab } from '../agent-work';
import { AgentTerminal, type AgentTerminalMessages } from './agent-terminal';
import type { AgentActiveCommand, AgentTerminalEntry } from './command-types';

export type AgentCodingMessages = {
	terminalTab: string;
};

export const defaultAgentCodingMessages: AgentCodingMessages = {
	terminalTab: '终端',
};

export type AgentCodingProps = Omit<AgentWorkProps, 'extraWorkspaceTabs'> & {
	activeCommand?: AgentActiveCommand;
	command: string;
	entries: readonly AgentTerminalEntry[];
	extraWorkspaceTabs?: readonly AgentWorkTab[];
	messages?: AgentWorkProps['messages'] & Partial<AgentCodingMessages>;
	onCancelCommand?: (id: string) => void;
	onCommandChange: (command: string) => void;
	onRunCommand?: (command: string) => void;
	poisoned?: boolean;
	terminalMessages?: Partial<AgentTerminalMessages>;
	terminalProps?: Omit<ComponentPropsWithRef<'section'>, 'children'>;
};

export function AgentCoding({
	activeCommand,
	command,
	entries,
	extraWorkspaceTabs = [],
	messages,
	onCancelCommand,
	onCommandChange,
	onRunCommand,
	poisoned,
	terminalMessages,
	terminalProps,
	...workProps
}: AgentCodingProps) {
	const fileManagerProps = {
		...workProps.fileManagerProps,
		readOnly: poisoned || workProps.fileManagerProps?.readOnly,
	};
	const codingCopy = { ...defaultAgentCodingMessages, ...messages };
	const terminal = (
		<AgentTerminal
			{...terminalProps}
			activeCommand={activeCommand}
			command={command}
			entries={entries}
			messages={terminalMessages}
			poisoned={poisoned}
			onCancel={onCancelCommand}
			onCommandChange={onCommandChange}
			onRun={onRunCommand}
		/>
	);
	return (
		<AgentWork
			{...workProps}
			fileManagerProps={fileManagerProps}
			workspaceReadOnly={poisoned}
			extraWorkspaceTabs={[
				{
					id: 'terminal',
					label: (
						<span className='inline-flex items-center gap-1.5'>
							<TerminalSquare aria-hidden='true' className='size-4' />
							{codingCopy.terminalTab}
						</span>
					),
					panel: terminal,
				},
				...extraWorkspaceTabs,
			]}
			messages={messages}
		/>
	);
}

export * from './agent-coding';
export * from './agent-terminal';
export * from './coding-tools';
export * from './command-runtime';
export * from './command-types';
export * from './just-bash-executor';
export * from './terminal-history';
